<?php
declare(strict_types=1);
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(404);exit;}
function platformShippingBook(array $d,array $u): array{
 platformAdmin($u);$key=platformSecret('BOSTA_API_KEY');$secret=platformSecret('bosta_webhook_secret');$location=platformConfig()['bosta_pickup_address_id']??'';if(!$key||strlen($secret)<32||!$location)accountError(503,'BOSTA_NOT_CONFIGURED');$id=accountString($d,'order_id',32,true);$city=accountString($d,'city_id',120,true);$district=accountString($d,'district_id',120,true);$package=accountString($d,'package_type',40,true);if(!in_array($package,['SMALL','MEDIUM','LARGE','Light Bulky','Heavy Bulky'],true))accountError(422,'INVALID_PACKAGE_TYPE');$count=platformInt($d,'item_count',1,1000);$description=accountString($d,'description',1000,true);
 $order=platformTransaction(function()use($id,$u){$o=accountQuery('SELECT * FROM idea_orders WHERE id=?'.platformLock(),[$id])->fetch();if(!$o||$o['status']!=='ready_to_ship'||($o['payment_status']!=='paid'&&$o['payment_method']!=='cash_on_delivery'))accountError(409,'ORDER_NOT_READY');if(accountQuery('SELECT id FROM idea_deliveries WHERE order_id=?',[$id])->fetch())accountError(409,'DELIVERY_ALREADY_CREATED');accountQuery('INSERT INTO idea_deliveries(id,order_id,provider,status,history,created_at,updated_at) VALUES(?,?,?,?,?,?,?)',[platformId(),$id,'bosta','booking','[]',platformNow(),platformNow()]);platformAudit($u,'delivery-booking',$id);return $o;});
 $address=json_decode($order['address_snapshot'],true);$names=preg_split('/\s+/',$address['recipient'],2);$api=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME'])),'/').'/platform.php';
 try{[$code,$r]=platformHttp('https://app.bosta.co/api/v2/deliveries?apiVersion=1',['Authorization: '.$key,'Content-Type: application/json'],['type'=>10,'businessReference'=>$id,'businessLocationId'=>$location,'dropOffAddress'=>['city'=>$city,'districtId'=>$district,'firstLine'=>$address['street'].' / '.$address['building'],'secondLine'=>$address['floor_number'].' / '.$address['apartment'],'floor'=>$address['floor_number'],'apartment'=>$address['apartment']],'receiver'=>['firstName'=>$names[0],'lastName'=>$names[1]??$names[0],'phone'=>$address['phone']],'specs'=>['packageType'=>$package,'packageDetails'=>['description'=>$description,'itemsCount'=>$count]],'cod'=>$order['payment_method']==='cash_on_delivery'?(int)$order['total_cents']/100:0,'webhookUrl'=>rtrim(accountConfig()['site_url'],'/').$api.'?action=delivery-webhook','webhookCustomHeaders'=>['X-IDEA-Webhook-Token'=>$secret]]);$result=$r['data']??[];if($code<200||$code>=300||empty($result['_id'])||empty($result['trackingNumber']))accountError(502,'BOSTA_BOOKING_FAILED');accountQuery("UPDATE idea_deliveries SET provider_id=?,tracking_number=?,status='booked',updated_at=? WHERE order_id=?",[(string)$result['_id'],(string)$result['trackingNumber'],platformNow(),$id]);return ['tracking_number'=>(string)$result['trackingNumber'],'status'=>'booked'];}catch(Throwable $e){accountQuery("UPDATE idea_deliveries SET status='booking_unknown',updated_at=? WHERE order_id=?",[platformNow(),$id]);throw $e;}
}
function platformShippingWebhook(string $raw): array{
 $secret=platformSecret('bosta_webhook_secret');$given=$_SERVER['HTTP_X_IDEA_WEBHOOK_TOKEN']??'';if(strlen($secret)<32)accountError(503,'BOSTA_NOT_CONFIGURED');if(!is_string($given)||!hash_equals($secret,$given))accountError(403,'DELIVERY_SIGNATURE_INVALID');$d=json_decode($raw,true);if(!is_array($d)||!is_int($d['state']??null)||!is_int($d['timeStamp']??null))accountError(400,'DELIVERY_CALLBACK_INVALID');$id=accountString($d,'_id',120,true);
 return platformTransaction(function()use($d,$id){$r=accountQuery('SELECT * FROM idea_deliveries WHERE provider=? AND provider_id=?'.platformLock(),['bosta',$id])->fetch();if(!$r)accountError(404,'DELIVERY_NOT_FOUND');if((string)($d['trackingNumber']??'')!==$r['tracking_number'])accountError(409,'DELIVERY_DETAILS_MISMATCH');$history=json_decode($r['history'],true)?:[];foreach($history as $old)if(($old['time']??0)===$d['timeStamp']&&($old['code']??0)===$d['state'])return ['received'=>true,'duplicate'=>true];$map=[10=>'booked',20=>'route_assigned',21=>'picked_up',23=>'picked_up',24=>'at_warehouse',30=>'in_transit',41=>'out_for_delivery',45=>'delivered',46=>'returned',47=>'exception',48=>'terminated',49=>'cancelled',100=>'lost',101=>'damaged'];$state=$map[$d['state']]??'provider_state_'.$d['state'];$newer=!$history||max(array_column($history,'time'))<=$d['timeStamp'];$history[]=['status'=>$state,'code'=>$d['state'],'time'=>$d['timeStamp'],'source'=>'bosta'];accountQuery('UPDATE idea_deliveries SET status=?,history=?,updated_at=? WHERE id=?',[$newer?$state:$r['status'],platformJson(array_slice($history,-200)),platformNow(),$r['id']]);if($newer&&$state==='delivered')accountQuery("UPDATE idea_orders SET status='delivered',updated_at=? WHERE id=? AND status IN ('ready_to_ship','shipped')",[platformNow(),$r['order_id']]);return ['received'=>true];});
}
